def background(grid, mark=None):
    """The most common cell color that is not the mark color."""
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    return max((c for c in counts if c != mark), key=lambda c: counts[c])

def nonbackground_color(grid, bg=None):
    """The color that is not the background: the rarest color (or mark) in the grid."""
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    return min(counts, key=lambda c: counts[c])

def fills_between(grid, mark, fill):
    """Fill every cell between two consecutive cells of color mark (in a row or column) with color fill."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for i in range(h):
        js = [j for j in range(w) if grid[i][j] == mark]
        for a, b in zip(js, js[1:]):
            for j in range(a + 1, b):
                out[i][j] = fill
    for j in range(w):
        iss = [i for i in range(h) if grid[i][j] == mark]
        for a, b in zip(iss, iss[1:]):
            for i in range(a + 1, b):
                out[i][j] = fill
    return out

